import{_ as l,o as i,c as s,ai as n}from"./chunks/framework.Ba-VnP44.js";const o=JSON.parse('{"title":"AI 编程效率 SOP","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/coding-sop/index.md","filePath":"ai/productivity/coding-sop/index.md"}'),e={name:"ai/productivity/coding-sop/index.md"};function r(t,a,p,d,h,c){return i(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="ai-编程效率-sop" tabindex="-1">AI 编程效率 SOP <a class="header-anchor" href="#ai-编程效率-sop" aria-label="Permalink to “AI 编程效率 SOP”">​</a></h1><blockquote><p>一套可以直接用于 Cursor、WorkBuddy 等 AI 编程工具的实战操作手册。目标是减少重复沟通、开发弯路、无效修改和返工，让 AI 尽可能自主完成从任务理解到测试交付的全过程。</p></blockquote><h2 id="这套手册解决什么问题" tabindex="-1">这套手册解决什么问题？ <a class="header-anchor" href="#这套手册解决什么问题" aria-label="Permalink to “这套手册解决什么问题？”">​</a></h2><p>日常使用 AI 编程时，最浪费时间的往往不是写代码，而是：</p><ul><li>反复解释项目背景和业务需求。</li><li>AI 没理解项目就开始修改代码。</li><li>方案没有确定，写到一半才发现方向错误。</li><li>每完成一小步都要人工提醒下一步。</li><li>AI 修改代码后没有主动编译和测试。</li><li>一个错误反复修复，甚至引入新的问题。</li><li>每个新项目都要重新告诉 AI 一遍开发规范。</li></ul><p>这套 SOP 就是为了解决这些问题。</p><h2 id="一、日常开发主流程" tabindex="-1">一、日常开发主流程 <a class="header-anchor" href="#一、日常开发主流程" aria-label="Permalink to “一、日常开发主流程”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>接到开发任务</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>判断任务类型与风险</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>准备必要的项目上下文</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>明确需求与验收标准</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>分析影响范围</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>制定技术方案和实施计划</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>确认执行边界</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>AI 连续执行开发</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>编译、测试、问题修复</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>代码审查与结果验收</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>交付与经验沉淀</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>不是每个小任务都需要完整走一遍。</p><p>例如：</p><ul><li>修改一个简单文案：直接定位、修改、检查即可。</li><li>修复一个明确的小 Bug：复现问题、定位原因、修改、回归测试。</li><li>增加一个业务模块：完整走需求分析、方案设计、开发和测试流程。</li><li>接手一个陌生老项目：先完成项目接入，再开始业务开发。</li></ul><h2 id="二、根据开发场景选择入口" tabindex="-1">二、根据开发场景选择入口 <a class="header-anchor" href="#二、根据开发场景选择入口" aria-label="Permalink to “二、根据开发场景选择入口”">​</a></h2><table tabindex="0"><thead><tr><th>当前场景</th><th>优先使用</th></tr></thead><tbody><tr><td>全新项目，准备开始开发</td><td>01 项目初始化与 AI 接入</td></tr><tr><td>接手一个陌生项目</td><td>01 项目初始化与 AI 接入</td></tr><tr><td>AI 总是理解错需求</td><td>02 开发任务输入规范</td></tr><tr><td>AI 找不到正确的代码位置</td><td>03 项目分析与上下文准备</td></tr><tr><td>AI 直接编码，导致方向错误</td><td>04 技术方案与任务拆解</td></tr><tr><td>想建立可复用的 AI 编程配置</td><td>05 Rules、Agent、Skills 实战配置</td></tr><tr><td>希望 AI 一次连续完成多个开发步骤</td><td>06 AI 连续开发与任务执行</td></tr><tr><td>AI 修改后频繁报错、返工</td><td>07 报错排查、测试与自动修复</td></tr><tr><td>任务完成后需要检查和复用经验</td><td>08 交付验收与经验复用</td></tr></tbody></table><h2 id="三、不同任务采用不同执行强度" tabindex="-1">三、不同任务采用不同执行强度 <a class="header-anchor" href="#三、不同任务采用不同执行强度" aria-label="Permalink to “三、不同任务采用不同执行强度”">​</a></h2><p>不要为了流程完整而增加不必要的操作。</p><table tabindex="0"><thead><tr><th>任务类型</th><th>推荐执行方式</th></tr></thead><tbody><tr><td>简单修改</td><td>定位 → 修改 → 检查</td></tr><tr><td>小型 Bug</td><td>复现 → 定位 → 修复 → 回归</td></tr><tr><td>普通功能</td><td>需求 → 分析 → 计划 → 开发 → 测试</td></tr><tr><td>复杂功能</td><td>需求分析 → 方案设计 → 分阶段开发 → 阶段验证</td></tr><tr><td>大型项目</td><td>项目接入 → 建立上下文 → 协作配置 → 任务执行</td></tr><tr><td>高风险改动</td><td>影响分析 → 备份或隔离 → 方案确认 → 实施 → 专项验证</td></tr></tbody></table><p>判断标准：</p><ol><li>修改范围越大，前期分析越充分。</li><li>影响数据、权限、资金、库存等核心业务时，提高验证强度。</li><li>项目越陌生，越应该先理解现状。</li><li>越简单的任务，越不应该引入复杂流程。</li></ol><h2 id="四、八个实战章节" tabindex="-1">四、八个实战章节 <a class="header-anchor" href="#四、八个实战章节" aria-label="Permalink to “四、八个实战章节”">​</a></h2><h3 id="_01-项目初始化与-ai-接入" tabindex="-1">01 项目初始化与 AI 接入 <a class="header-anchor" href="#_01-项目初始化与-ai-接入" aria-label="Permalink to “01 项目初始化与 AI 接入”">​</a></h3><p>解决新项目和老项目如何快速建立 AI 开发环境的问题。</p><p>包括：</p><ul><li>新项目初始化。</li><li>老项目接管。</li><li>项目基础信息收集。</li><li>项目规则文件准备。</li><li>AI 接入验收。</li></ul><p><a href="/my-vitepress-site/ai/productivity/coding-sop/01-project-init.html">进入第 01 章</a></p><h3 id="_02-开发任务输入规范" tabindex="-1">02 开发任务输入规范 <a class="header-anchor" href="#_02-开发任务输入规范" aria-label="Permalink to “02 开发任务输入规范”">​</a></h3><p>解决需求反复解释、AI 理解偏差的问题。</p><p>包括：</p><ul><li>任务描述模板。</li><li>背景、目标、约束、验收标准。</li><li>新功能、Bug、重构等不同任务的输入方式。</li><li>需求澄清与提问规则。</li></ul><h3 id="_03-项目分析与上下文准备" tabindex="-1">03 项目分析与上下文准备 <a class="header-anchor" href="#_03-项目分析与上下文准备" aria-label="Permalink to “03 项目分析与上下文准备”">​</a></h3><p>解决 AI 不知道该看哪些文件、不了解业务调用链的问题。</p><p>包括：</p><ul><li>如何定位相关代码。</li><li>如何分析模块依赖。</li><li>如何识别接口、数据库和业务影响。</li><li>如何避免无效的全仓扫描。</li><li>如何向 AI 提供足够但不过量的上下文。</li></ul><h3 id="_04-技术方案与任务拆解" tabindex="-1">04 技术方案与任务拆解 <a class="header-anchor" href="#_04-技术方案与任务拆解" aria-label="Permalink to “04 技术方案与任务拆解”">​</a></h3><p>解决 AI 没有方案就开始写代码的问题。</p><p>包括：</p><ul><li>修改前影响分析。</li><li>技术方案比较。</li><li>实施步骤拆分。</li><li>任务依赖关系。</li><li>每个步骤的完成标准。</li></ul><h3 id="_05-rules、agent、skills-实战配置" tabindex="-1">05 Rules、Agent、Skills 实战配置 <a class="header-anchor" href="#_05-rules、agent、skills-实战配置" aria-label="Permalink to “05 Rules、Agent、Skills 实战配置”">​</a></h3><p>解决 AI 开发规范无法复用、重复指挥的问题。</p><p>包括：</p><ul><li>Rules 配置。</li><li>Agent 分工。</li><li>Skills 封装。</li><li>MCP 与 Hooks 的使用边界。</li><li>Cursor、WorkBuddy 等工具适配。</li></ul><h3 id="_06-ai-连续开发与任务执行" tabindex="-1">06 AI 连续开发与任务执行 <a class="header-anchor" href="#_06-ai-连续开发与任务执行" aria-label="Permalink to “06 AI 连续开发与任务执行”">​</a></h3><p>解决 AI 每完成一步都等待人工指令的问题。</p><p>包括：</p><ul><li>连续任务执行。</li><li>阶段性检查点。</li><li>串行与并行执行。</li><li>修改范围控制。</li><li>长任务进度记录。</li><li>异常时暂停与恢复。</li></ul><h3 id="_07-报错排查、测试与自动修复" tabindex="-1">07 报错排查、测试与自动修复 <a class="header-anchor" href="#_07-报错排查、测试与自动修复" aria-label="Permalink to “07 报错排查、测试与自动修复”">​</a></h3><p>解决 AI 修改代码后没有验证、错误反复出现的问题。</p><p>包括：</p><ul><li>编译和测试。</li><li>错误定位。</li><li>根因分析。</li><li>自动修复循环。</li><li>回归验证。</li><li>防止无限修改。</li></ul><h3 id="_08-交付验收与经验复用" tabindex="-1">08 交付验收与经验复用 <a class="header-anchor" href="#_08-交付验收与经验复用" aria-label="Permalink to “08 交付验收与经验复用”">​</a></h3><p>解决 AI 只汇报代码写完，却无法证明任务真正完成的问题。</p><p>包括：</p><ul><li>需求逐项验收。</li><li>Git Diff 检查。</li><li>测试证据。</li><li>文档同步。</li><li>交付报告。</li><li>Rules 和 Skills 经验沉淀。</li></ul><h2 id="五、使用原则" tabindex="-1">五、使用原则 <a class="header-anchor" href="#五、使用原则" aria-label="Permalink to “五、使用原则”">​</a></h2><h3 id="原则-1-先理解-再修改" tabindex="-1">原则 1：先理解，再修改 <a class="header-anchor" href="#原则-1-先理解-再修改" aria-label="Permalink to “原则 1：先理解，再修改”">​</a></h3><p>AI 必须先了解与任务相关的现有代码和业务逻辑，不能只根据用户的一句话猜测项目结构。</p><h3 id="原则-2-简单任务简单处理" tabindex="-1">原则 2：简单任务简单处理 <a class="header-anchor" href="#原则-2-简单任务简单处理" aria-label="Permalink to “原则 2：简单任务简单处理”">​</a></h3><p>不要为了完成一个小修改，先建立复杂的 Agent 团队或生成大量项目文档。</p><h3 id="原则-3-能自主完成的事情不要交给用户" tabindex="-1">原则 3：能自主完成的事情不要交给用户 <a class="header-anchor" href="#原则-3-能自主完成的事情不要交给用户" aria-label="Permalink to “原则 3：能自主完成的事情不要交给用户”">​</a></h3><p>AI 应主动检查代码、执行命令、运行测试、分析报错。</p><p>只有权限不足、信息缺失、操作风险或关键决策需要人工确认时，才向用户求助。</p><h3 id="原则-4-重要操作必须有证据" tabindex="-1">原则 4：重要操作必须有证据 <a class="header-anchor" href="#原则-4-重要操作必须有证据" aria-label="Permalink to “原则 4：重要操作必须有证据”">​</a></h3><p>不能仅凭 AI 自己说完成了，就认为任务完成。</p><p>应该提供实际修改内容、命令执行结果、测试结果和未解决问题。</p><h3 id="原则-5-有效经验才沉淀" tabindex="-1">原则 5：有效经验才沉淀 <a class="header-anchor" href="#原则-5-有效经验才沉淀" aria-label="Permalink to “原则 5：有效经验才沉淀”">​</a></h3><p>一次性问题不一定需要增加 Rules 或 Skills。</p><p>只有具有重复价值的经验，才应该固化为可复用资产。</p><h2 id="六、最终希望形成的工作方式" tabindex="-1">六、最终希望形成的工作方式 <a class="header-anchor" href="#六、最终希望形成的工作方式" aria-label="Permalink to “六、最终希望形成的工作方式”">​</a></h2><p>以后面对一个开发任务：</p><ol><li>我只需要把任务交代清楚。</li><li>AI 自己理解项目和需求。</li><li>AI 主动分析影响范围和实施方案。</li><li>AI 按计划连续完成开发。</li><li>AI 自己编译、测试、定位和修复问题。</li><li>AI 给出真实的完成情况和验收证据。</li><li>有价值的经验自动进入后续优化流程。</li></ol><p>这就是这套 SOP 的最终目标。</p><hr>`,71)])])}const u=l(e,[["render",r]]);export{o as __pageData,u as default};
